package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Method;

import static org.junit.jupiter.api.Assertions.*;

class OptionHasLongOptTest {

    @Test
    void hasLongOpt_isFalse_whenNotSetByConstructor() throws Exception {
        Option opt = new Option("a", "description");
        assertFalse(opt.hasLongOpt(), "hasLongOpt should be false when longOption is not set");
    }

    @Test
    void hasLongOpt_isTrue_whenSetViaConstructor() throws Exception {
        Option opt = new Option("a", "longOpt", false, "description");
        assertTrue(opt.hasLongOpt(), "hasLongOpt should be true when longOption provided in constructor");
    }

    @Test
    void hasLongOpt_changes_whenUsingSetter() throws Exception {
        Option opt = new Option("a", false, "description");
        // Initially false
        assertFalse(opt.hasLongOpt(), "initial hasLongOpt should be false");
        // Set long option -> true
        opt.setLongOpt("verbose");
        assertTrue(opt.hasLongOpt(), "hasLongOpt should be true after setting a non-null long option");
        // Clear long option -> false
        opt.setLongOpt(null);
        assertFalse(opt.hasLongOpt(), "hasLongOpt should be false after clearing the long option (set to null)");
    }

    @Test
    void private_hasNoValues_reflectively_invoked_affectsExpectation() throws Exception {
        Option opt = new Option("x", "description");

        // Access private boolean hasNoValues() via reflection
        Method hasNoValues = Option.class.getDeclaredMethod("hasNoValues");
        hasNoValues.setAccessible(true);

        // Initially, no values -> should be true
        boolean initiallyNoValues = (boolean) hasNoValues.invoke(opt);
        assertTrue(initiallyNoValues, "Initially there should be no values");

        // Add a value using the public (deprecated) API
        opt.addValue("val1");

        // Now, hasNoValues should return false
        boolean afterAddNoValues = (boolean) hasNoValues.invoke(opt);
        assertFalse(afterAddNoValues, "After adding a value, hasNoValues should be false");

        // Ensure long option unrelated state remains consistent
        assertFalse(opt.hasLongOpt(), "hasLongOpt should remain false (no long option set)");
        opt.setLongOpt("lopt");
        assertTrue(opt.hasLongOpt(), "hasLongOpt should be true after setting via setter");
    }
}

